import json, requests, sys

webhook = "https://open.feishu.cn/open-apis/bot/v2/hook/39ace5b8-ddf6-4ccf-8912-2c2681c618a4"

card = {
    "msg_type": "interactive",
    "card": {
        "header": {
            "title": {"tag": "plain_text", "content": "🔔 澳洲冰箱新品巡检 - 2026年6月26日 下午"},
            "template": "blue"
        },
        "elements": [
            {
                "tag": "div",
                "text": {
                    "tag": "lark_md",
                    "content": "**巡检时间：** 2026-06-26 15:45 (GMT+8)\n\n---\n\n### 📊 巡检结果：发现 2 项库存状态变化\n\n---\n\n**🏷️ 海信 Hisense**\n\n| 型号 | 产品 | 价格 | 变化 |\n|------|------|------|------|\n| HRBM419SW | 415L Bottom Mount w/ Water Dispenser SS | $1,199 | 🔴缺货 → 🟢有货 |\n| HRTF497SW | 496L Silver Top Mount Fridge | $1,099 | 🟢有货 → 🔴缺货 |\n\n---\n\n**🏷️ 美的 Midea** — 无变化\n- MDRT580MTF45AP (413L) 仍为 Coming Soon\n\n**🏷️ 三星 Samsung** — 搜索无新发现\n\n**🏷️ LG** — 搜索无新发现\n\n**🏷️ 西屋 Westinghouse** — 无变化"
                }
            },
            {
                "tag": "hr"
            },
            {
                "tag": "note",
                "elements": [
                    {"tag": "plain_text", "content": "由 Incaier Agent 自动巡检"}
                ]
            }
        ]
    }
}

resp = requests.post(webhook, json=card, timeout=15)
result = {"status_code": resp.status_code, "body": resp.json()}
with open(sys.argv[-1], 'w', encoding='utf-8') as f:
    json.dump(result, f, ensure_ascii=False, indent=2)
print("Done:", resp.status_code, resp.json())

